<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {RouterLink,useRoute} from 'vue-router';
import {useApplication} from '../../application';import WorkspaceTopbar from '../../shared/WorkspaceTopbar.vue';import OperationsRecovery from './OperationsRecovery.vue';import SendMinutesDialog from '../mail/SendMinutesDialog.vue';
import type {Voiceprint,Dataset,Evaluation,EvaluationDetail,Configuration,ModelConfiguration,Sample} from './operations-types';
const app=useApplication(),ops=app.operationsCommands,route=useRoute(),tab=ref('voiceprints'),error=ref(''),notice=ref(''),loading=ref(false),busy=ref(false),reviewer=ref(false);
const voices=ref<Voiceprint[]>([]),datasets=ref<Dataset[]>([]),runs=ref<Evaluation[]>([]),detail=ref<EvaluationDetail|null>(null),config=ref<Configuration|null>(null),corpus=ref<{id:string;category:string;comment:string;approvedRevisionToken:string;sourceRevisionToken:string}[]>([]);
const consent=ref(''),agreed=ref(false),days=ref(30),voiceFile=ref<File|null>(null),voiceName=ref(''),reason=ref(''),matchResults=ref<{voiceprintId:string;subjectId:string;modelVersion:string;score:number}[]>([]);
const datasetVersion=ref(''),samples=ref<Sample[]>([]),kind=ref<Sample['kind']>('ASR'),sampleText=ref(''),reference=ref(''),firstFile=ref<File|null>(null),secondFile=ref<File|null>(null),datasetId=ref(''),threshold=ref(''),runId=ref(''),rollbackRevision=ref('0');
const sourceMeeting=ref(''),sourceRevision=ref(''),segmentIds=ref(''),category=ref('WORDING'),comment=ref(''),withdrawId=ref('');
const mail=ref<InstanceType<typeof SendMinutesDialog>>();
const disabled=computed(()=>busy.value||loading.value||ops.pending.value||!ops.available.value),actor=()=>app.session.current.value?.actor.enterpriseId??null;let epoch=0;
function clear(){epoch++;loading.value=false;busy.value=false;datasetId.value='';datasetVersion.value='';threshold.value='';runId.value='';rollbackRevision.value='0';voices.value=[];datasets.value=[];runs.value=[];detail.value=null;config.value=null;corpus.value=[];reviewer.value=false;consent.value='';agreed.value=false;voiceFile.value=null;voiceName.value='';reason.value='';matchResults.value=[];samples.value=[];sampleText.value='';reference.value='';firstFile.value=null;secondFile.value=null;sourceMeeting.value='';sourceRevision.value='';segmentIds.value='';comment.value='';withdrawId.value='';notice.value='';error.value='';}
function failure(cause:unknown){if(cause instanceof Error&&cause.name==='AbortError')return;error.value=cause instanceof Error?cause.message:'运营服务暂不可用。';if(!ops.available.value){clear();error.value='当前治理权限已失效，请重新检查登录。';}}
async function recheck(){try{await app.session.refresh();await reload();}catch(cause){failure(cause);}}
async function reload(){const turn=epoch;if(!actor()||!ops.available.value)return;loading.value=true;error.value='';try{const capabilities=await ops.read<{reviewer:boolean}>('/api/v1/operations/capabilities');if(turn!==epoch)return;reviewer.value=capabilities.reviewer;const v=await ops.read<Voiceprint[]>('/api/v1/operations/voiceprints');if(turn!==epoch)return;voices.value=v;if(reviewer.value){const [d,r,c,a]=await Promise.all([ops.read<Dataset[]>('/api/v1/operations/datasets'),ops.read<Evaluation[]>('/api/v1/operations/evaluations'),ops.read<Configuration>('/api/v1/operations/configuration'),ops.read<typeof corpus.value>('/api/v1/operations/corpus')]);if(turn!==epoch)return;datasets.value=d;runs.value=r;config.value=c;corpus.value=a;}}catch(cause){if(turn===epoch)failure(cause);}finally{if(turn===epoch)loading.value=false;}}
async function run(action:()=>Promise<unknown>,success:string){const turn=epoch;if(disabled.value)return;busy.value=true;error.value='';notice.value='';try{await action();if(turn!==epoch)return;notice.value=success;await reload();}catch(cause){if(turn===epoch)failure(cause);}finally{if(turn===epoch)busy.value=false;}}
async function base64(file:File|null){if(!file||file.size<96044||file.size>960044)throw new Error('请选择3至30秒的16kHz单声道16位WAV文件。');const bytes=new Uint8Array(await file.arrayBuffer());let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s);}
function file(event:Event,which:'voice'|'first'|'second'){const chosen=(event.target as HTMLInputElement).files?.[0]??null;if(which==='voice'){voiceFile.value=chosen;voiceName.value=chosen?.name??'';}else if(which==='first')firstFile.value=chosen;else secondFile.value=chosen;}
async function enroll(){await run(async()=>{if(!agreed.value||!consent.value.trim()||!Number.isInteger(days.value)||days.value<1||days.value>365)throw new Error('请明确同意用途、填写凭据并设置有效期限。');const scope=epoch,who=actor(),file=voiceFile.value;const value=await base64(file);if(scope!==epoch||who!==actor())throw new DOMException('Identity changed','AbortError');await ops.submit('/api/v1/operations/voiceprints',{consentReference:consent.value,expiresAt:new Date(Date.now()+days.value*86400000).toISOString(),wavBase64:value});voiceFile.value=null;voiceName.value='';consent.value='';agreed.value=false;},'声纹已提交审核。');}
function voiceAction(v:Voiceprint,decision?:'APPROVED'|'REJECTED'){return run(()=>ops.submit(`/api/v1/operations/voiceprints/${v.id}/${decision?'review':'revocation'}`,{expectedRevisionToken:v.revisionToken,...(decision?{decision}:{}),reason:reason.value}),decision?'审核已记录。':'授权已撤销，特征已清理。');}
async function match(){await run(async()=>{const scope=epoch,who=actor(),audio=await base64(voiceFile.value);if(scope!==epoch||who!==actor())throw new DOMException('Identity changed','AbortError');const result=await ops.submit('/api/v1/operations/voiceprints/match',{wavBase64:audio}) as typeof matchResults.value;if(scope===epoch)matchResults.value=result;},'候选仅供人工核对，不授予会议权限。');}
async function addSample(){error.value='';const turn=epoch;try{if(samples.value.length>=50)throw new Error('每个版本最多50个样本。');let input:string,input2:string|null=null,expected=reference.value;if(kind.value==='MINUTES')input=sampleText.value;else input=await base64(firstFile.value);if(kind.value==='VOICE_SAME'||kind.value==='VOICE_DIFFERENT'){input2=await base64(secondFile.value);expected=kind.value==='VOICE_SAME'?'true':'false';}if(!input.trim()||!expected.trim())throw new Error('请填写样本输入与参考答案。');if(turn===epoch)samples.value=[...samples.value,{id:'sample-'+(samples.value.length+1),kind:kind.value,input,input2,expected}];}catch(cause){if(turn===epoch)failure(cause);}}
const candidate=computed<ModelConfiguration>(()=>({modelVersion:'harness-embed-v1',promptVersion:'summary-v1',voiceThreshold:threshold.value===''?null:Number(threshold.value)}));
function createDataset(){return run(async()=>{await ops.submit('/api/v1/operations/datasets',{version:datasetVersion.value,samples:samples.value});samples.value=[];datasetVersion.value='';},'不可变数据集版本已保存。');}
function evaluate(){return run(async()=>{const value=await ops.submit('/api/v1/operations/evaluations',{datasetId:datasetId.value,configuration:candidate.value}) as {id:string};runId.value=value.id;},'评测已排队，结果包含失败样本。');}
async function readRun(id:string){const turn=epoch;error.value='';try{const result=await ops.read<EvaluationDetail>('/api/v1/operations/evaluations/'+id);if(turn===epoch){detail.value=result;runId.value=id;}}catch(cause){if(turn===epoch)failure(cause);}}
function reviewRun(){return run(async()=>{if(!detail.value)throw new Error('请先读取评测。');await ops.submit(`/api/v1/operations/evaluations/${detail.value.id}/review`,{reason:reason.value});await readRun(detail.value.id);},'人工复核意见已记录。');}
function release(){return run(()=>{if(!detail.value||!config.value)throw new Error('请先读取评测及当前配置。');return ops.submit('/api/v1/operations/configuration-releases',{expectedRevisionToken:config.value.revisionToken,evaluationId:detail.value.id,configuration:detail.value.configuration,reason:reason.value});},'新配置修订已发布。');}
function rollback(){return run(()=>{if(!config.value)throw new Error('请先读取配置。');return ops.submit('/api/v1/operations/configuration-rollbacks',{expectedRevisionToken:config.value.revisionToken,targetRevisionToken:rollbackRevision.value,reason:reason.value});},'回滚已创建新修订，历史与在途任务快照保留。');}
function submitCorpus(){return run(async()=>{const result=await ops.submit(`/api/v1/meetings/${sourceMeeting.value}/feedback`,{sourceRevisionToken:sourceRevision.value,segmentIds:segmentIds.value.split(/[\s,，]+/).filter(Boolean),category:category.value,comment:comment.value}) as {id:string};withdrawId.value=result.id;comment.value='';},'源版本绑定的反馈已提交，审核前不会投入语料。');}
function withdraw(){return run(()=>ops.submit(`/api/v1/operations/corpus/${withdrawId.value}/withdrawal`,{}),'反馈已撤回，不再提供给语料消费。');}
const stop=watch(actor,who=>{clear();busy.value=false;loading.value=false;if(who)void reload();},{immediate:true,flush:'sync'});
watch(()=>ops.pending.value,(pending,was)=>{if(was&&!pending)void reload();});
watch([()=>route.query.meetingId,()=>mail.value,actor],([id,modal,who])=>{if(typeof id==='string'&&modal&&who)void modal.open(id);},{flush:'post',immediate:true});
watch(()=>ops.available.value,available=>{if(!available)clear();},{flush:'sync'});
onUnmounted(()=>{epoch++;stop();});
</script>
<template><div class="layout"><div class="main"><WorkspaceTopbar breadcrumb="运营治理"/><main class="content operations-page">
 <div class="page-head"><div><h1 class="page-title">运营治理</h1><p class="page-desc">管理明确授权的数据用途、质量记录与配置修订。</p></div><button class="btn" :disabled="loading||busy" @click="reload">刷新当前记录</button></div>
 <OperationsRecovery/><button v-if="actor()&&!ops.available.value" class="btn" @click="recheck">重新检查登录</button><p v-if="error||app.operationsScopeError.value" class="banner error" role="alert">{{error||app.operationsScopeError.value}}</p><p v-if="notice" class="banner success" role="status">{{notice}}</p>
 <div v-if="!actor()" class="card empty"><h2>请登录企业账号</h2><RouterLink class="btn primary" to="/login">企业登录</RouterLink></div>
 <template v-else><nav class="tabs" aria-label="治理功能"><button class="tab" :class="{active:tab==='voiceprints'}" @click="tab='voiceprints'">我的声纹</button><button class="tab" :class="{active:tab==='corpus'}" @click="tab='corpus'">语料反馈</button><button v-if="reviewer" class="tab" :class="{active:tab==='evaluation'}" @click="tab='evaluation'">质量评测</button><button v-if="reviewer" class="tab" :class="{active:tab==='configuration'}" @click="tab='configuration'">系统配置</button></nav>
 <section v-if="tab==='voiceprints'" class="card ops-section"><h2>{{reviewer?'声纹登记与审核':'我的声纹授权'}}</h2><p class="muted">用途仅为说话人候选识别。匹配结果须人工核对；撤销将清理已保存特征。原音频仅用于此次处理。</p>
 <div class="ops-fields"><label>同意凭据<input v-model="consent" class="input" maxlength="1024" placeholder="授权记录编号或本人同意说明" :disabled="disabled"/></label><label>有效天数<input v-model.number="days" class="input" type="number" min="1" max="365" :disabled="disabled"/></label><label>本人语音样本<input type="file" aria-label="本人语音样本" aria-describedby="voice-sample-requirements" accept=".wav,audio/wav" :disabled="disabled" @change="file($event,'voice')"/><span id="voice-sample-requirements" class="small muted">3至30秒 · 16kHz · 单声道 · 16位WAV</span></label></div>
 <label class="ops-consent"><input v-model="agreed" type="checkbox" :disabled="disabled"/>我同意将本人声纹在所填期限内用于说话人候选识别，并知悉可随时撤销。</label><div class="ops-actions"><button class="btn primary" :disabled="disabled||!agreed||!consent.trim()||!voiceFile" @click="enroll">登记本人声纹</button><button v-if="reviewer" class="btn" :disabled="disabled||!voiceFile||config?.configuration.voiceThreshold===null" @click="match">核对匹配候选</button><span class="muted">{{voiceName}}</span></div>
 <p v-if="reviewer&&config?.configuration.voiceThreshold===null" class="banner info">尚未发布经正负样本评测的阈值，候选匹配关闭。</p><p v-if="matchResults.length" role="status">候选：<span v-for="r in matchResults" :key="r.voiceprintId">{{r.subjectId}}（{{r.score.toFixed(3)}}，{{r.modelVersion}}） </span></p>
 <label class="ops-reason">审核或撤销原因<textarea v-model="reason" class="textarea" maxlength="2048" :disabled="disabled"/></label><div class="ops-table"><table><thead><tr><th>本人／主体</th><th>状态</th><th>期限</th><th>版本</th><th>处理</th></tr></thead><tbody><tr v-for="v in voices" :key="v.id"><td>{{v.subjectId}}</td><td>{{v.state}}</td><td>{{v.expiresAt.slice(0,10)}}</td><td>{{v.modelVersion}} · {{v.revisionToken}}</td><td><button v-if="reviewer&&v.state==='PENDING'&&v.subjectId!==actor()" class="btn sm" :disabled="disabled||!reason.trim()" @click="voiceAction(v,'APPROVED')">批准</button><button v-if="reviewer&&v.state==='PENDING'&&v.subjectId!==actor()" class="btn sm" :disabled="disabled||!reason.trim()" @click="voiceAction(v,'REJECTED')">拒绝</button><button v-if="v.subjectId===actor()&&v.state!=='REVOKED'" class="btn sm danger" :disabled="disabled||!reason.trim()" @click="voiceAction(v)">撤销授权</button></td></tr><tr v-if="!voices.length"><td colspan="5" class="empty">暂无声纹登记</td></tr></tbody></table></div></section>
 <section v-if="tab==='corpus'" class="card ops-section"><h2>版本绑定的语料反馈</h2><p class="muted">只提交你主动选择的建议。审核者不会因此获得源会议全文权限。</p><div class="ops-fields"><label>源会议编号<input v-model="sourceMeeting" class="input" :disabled="disabled"/></label><label>源会议版本<input v-model="sourceRevision" class="input" inputmode="numeric" :disabled="disabled"/></label><label>类别<select aria-label="类别" v-model="category" class="select" :disabled="disabled"><option value="WORDING">文字建议</option><option value="LABEL">标注建议</option><option value="ACTION_OWNER">负责人建议</option></select></label></div><label>段落编号（可留空，逗号或空格分隔）<textarea v-model="segmentIds" class="textarea" :disabled="disabled"/></label><label>反馈建议<textarea v-model="comment" class="textarea" maxlength="4096" :disabled="disabled"/></label><div class="ops-actions"><button class="btn primary" :disabled="disabled||!comment.trim()||!sourceMeeting||!sourceRevision" @click="submitCorpus">提交版本反馈</button><RouterLink to="/feedback" class="btn">查看我的反馈</RouterLink><RouterLink v-if="reviewer" to="/feedback?reviewing=1" class="btn">进入反馈审核队列</RouterLink></div><div class="ops-fields"><label>待撤回反馈编号<input v-model="withdrawId" class="input" :disabled="disabled"/></label><button class="btn danger" :disabled="disabled||!withdrawId" @click="withdraw">撤回本人反馈</button></div><template v-if="reviewer"><h3>当前有效的已批准语料</h3><p class="small muted">未绑定、未审核、源版本变化、删除、失效或撤回的反馈不会出现在此处。</p><div v-for="row in corpus" :key="row.id" class="ops-record"><b>{{row.category}} · 批准修订{{row.approvedRevisionToken}}</b><p>{{row.comment}}</p><span class="small muted">{{row.id}} · 来源版本{{row.sourceRevisionToken}}</span></div><p v-if="!corpus.length" class="empty">暂无有效批准语料</p></template></section>
 <section v-if="tab==='evaluation'&&reviewer" class="card ops-section"><h2>质量评测</h2><p class="banner info">报告保留失败和超时样本，并绑定数据集、模型和提示词版本。本地受控样本只证明协议和指标计算，不能代表真实模型质量。</p><h3>创建数据集版本</h3><div class="ops-fields"><label>版本标识<input v-model="datasetVersion" class="input" maxlength="128" :disabled="disabled"/></label><label>样本类型<select aria-label="样本类型" v-model="kind" class="select" :disabled="disabled"><option value="ASR">语音识别</option><option value="DIARIZATION">说话人数</option><option value="MINUTES">纪要</option><option value="VOICE_SAME">声纹：同一人</option><option value="VOICE_DIFFERENT">声纹：不同人</option></select></label></div><label v-if="kind==='MINUTES'">会议内容<textarea v-model="sampleText" class="textarea" maxlength="16384" :disabled="disabled"/></label><template v-else><label>第一份样本<input type="file" accept=".wav,audio/wav" :disabled="disabled" @change="file($event,'first')"/></label><label v-if="kind.startsWith('VOICE_')">第二份样本<input type="file" accept=".wav,audio/wav" :disabled="disabled" @change="file($event,'second')"/></label></template><label v-if="!kind.startsWith('VOICE_')">{{kind==='DIARIZATION'?'参考说话人数':'参考文本'}}<textarea v-model="reference" class="textarea" maxlength="8192" :disabled="disabled"/></label><div class="ops-actions"><button class="btn" :disabled="disabled" @click="addSample">加入样本</button><span>{{samples.length}} / 50 个样本</span><button class="btn" :disabled="disabled||!samples.length" @click="samples=[]">清空未提交样本</button><button class="btn primary" :disabled="disabled||!samples.length||!datasetVersion" @click="createDataset">保存数据集版本</button></div>
 <h3>运行评测</h3><div class="ops-fields"><label>数据集<select aria-label="数据集" v-model="datasetId" class="select" :disabled="disabled"><option value="">请选择版本</option><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.version}}（{{d.sampleCount}}样本）</option></select></label><label>候选匹配阈值（可留空）<input v-model="threshold" class="input" type="number" min="0.01" max="1" step="0.01" :disabled="disabled"/></label><button class="btn primary" :disabled="disabled||!datasetId" @click="evaluate">开始评测</button></div><p class="small muted">模型harness-embed-v1 · 提示词summary-v1 · 治理任务单并发，实时和离线语音工作忙时等待。</p><div class="ops-table"><table><thead><tr><th>数据集</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in runs" :key="r.id"><td>{{r.datasetVersion}}</td><td>{{r.state}}</td><td><button class="btn sm" :disabled="busy||loading" @click="readRun(r.id)">查看评测报告</button></td></tr></tbody></table></div>
 <section v-if="detail" class="ops-report" aria-label="评测报告"><h3>{{detail.datasetVersion}} · {{detail.state}}</h3><div class="ops-metrics"><span>总样本 <b>{{detail.metrics.sampleCount}}</b></span><span>成功 <b>{{detail.metrics.succeeded}}</b></span><span>失败 <b>{{detail.metrics.failed}}</b></span><span>待处理 <b>{{detail.metrics.pending}}</b></span><span>平均分 <b>{{detail.metrics.score.toFixed(3)}}</b></span></div><p>{{detail.configuration.modelVersion}} · {{detail.configuration.promptVersion}}</p><p v-for="r in detail.results" :key="r.id">{{r.id}} · {{r.succeeded?'成功':'失败'}} · {{r.score.toFixed(3)}} <span v-if="r.error">{{r.error}}</span></p><p v-if="detail.reviewReason">复核意见：{{detail.reviewReason}}</p><label>人工复核／发布意见<textarea v-model="reason" class="textarea" maxlength="2048" :disabled="disabled"/></label><div class="ops-actions"><button class="btn" :disabled="disabled||detail.state!=='COMPLETED'||!!detail.reviewedBy||!reason.trim()" @click="reviewRun">记录人工复核</button><button class="btn primary" :disabled="disabled||detail.state!=='COMPLETED'||!detail.reviewedBy||!!detail.metrics.failed||!reason.trim()" @click="release">发布本次评测配置</button><button class="btn" :disabled="busy" @click="readRun(detail.id)">刷新报告</button></div></section></section>
 <section v-if="tab==='configuration'&&reviewer" class="card ops-section"><h2>系统配置</h2><template v-if="config"><p>当前修订 <b>{{config.revisionToken}}</b> · {{config.configuration.modelVersion}} · {{config.configuration.promptVersion}}</p><p>候选阈值：{{config.configuration.voiceThreshold??'匹配关闭'}}</p><p class="muted">新发布和回滚都会创建修订；在途评测继续使用受理时的完整配置。</p><div class="ops-fields"><label>回滚到修订<select aria-label="回滚到修订" v-model="rollbackRevision" class="select" :disabled="disabled"><option v-for="h in config.history" :key="h.revisionToken" :value="h.revisionToken">修订{{h.revisionToken}} · {{h.reason}}</option></select></label><label>回滚原因<input v-model="reason" class="input" maxlength="2048" :disabled="disabled"/></label><button class="btn" :disabled="disabled||!reason.trim()" @click="rollback">创建回滚修订</button></div><div v-for="h in config.history" :key="h.revisionToken" class="ops-record"><b>修订{{h.revisionToken}}</b> · {{h.reason}}<p class="small muted">{{h.createdAt}}<span v-if="h.rollbackOf!==null"> · 回滚自{{h.rollbackOf}}</span></p></div></template></section>
 </template><SendMinutesDialog ref="mail"/></main></div></div></template>
<style scoped>
.operations-page{max-width:1552px;margin:auto}.ops-section{padding:24px;margin-top:20px}.ops-section h2{font-size:20px;margin:0 0 12px}.ops-section h3{margin:24px 0 12px}.ops-section label{display:flex;flex-direction:column;gap:8px;margin-bottom:16px;min-width:0}.ops-section .ops-consent{flex-direction:row;align-items:flex-start;line-height:1.6}.ops-fields{display:flex;gap:20px;align-items:flex-end;margin-top:16px}.ops-fields>label{flex:1}.ops-fields>.btn{margin-bottom:16px}.ops-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.ops-reason{max-width:700px}.ops-table{overflow:auto;margin-top:20px}.ops-table table{width:100%;border-collapse:collapse;text-align:left}.ops-table td,.ops-table th{padding:12px;border-bottom:1px solid var(--border);overflow-wrap:anywhere}.ops-table td .btn{margin:2px}.ops-record{padding:16px 0;border-top:1px solid var(--border);overflow-wrap:anywhere}.ops-record p{white-space:pre-wrap}.ops-metrics{display:flex;gap:24px;padding:20px;background:var(--bg);flex-wrap:wrap}.ops-report{border:1px solid var(--border);padding:20px;margin-top:24px;border-radius:8px}.ops-section .textarea{min-height:80px;width:100%;border:1px solid var(--border);border-radius:6px;padding:10px 12px;font:inherit;color:var(--text);background:white;resize:vertical;box-sizing:border-box}.ops-section .textarea:focus{outline:2px solid var(--orange);outline-offset:1px}.ops-section .banner{line-height:1.7}input[type=file]{max-width:100%}
</style>
